-- Friendship KeyChain: 20 pesanan simulasi dengan artwork 2D orisinal siap cetak.
-- Seluruh identitas dan transaksi adalah data fiktif untuk pengujian/laporan akademik.
-- Artwork SVG vektor disimpan di assets/demo-artworks/ dan ditautkan per order.
-- Aman dijalankan ulang: hanya menghapus baris dari batch simulasi ini dan batch demo lama.

DELETE FROM public.orders
WHERE notes LIKE '[DUMMY DATA - BAND TEST]%'
   OR notes LIKE '[SIMULASI ARTWORK - LAPORAN]%';


-- Verifikasi: hasil harus menampilkan 20 order simulasi dengan tautan SVG artwork.
SELECT id, customer_name, product_name, quantity, status,
       design->>'thumb' AS artwork_url
FROM public.orders
WHERE notes LIKE '[SIMULASI ARTWORK - LAPORAN]%'
ORDER BY created_at DESC;
